class Solution:
    def singleNumber(self, nums):
        # Step 1: XOR all numbers to get XOR of the two unique numbers
        xor_all = 0
        for num in nums:
            xor_all ^= num

        # Step 2: Find the rightmost set bit
        # Using bit manipulation trick: xor_all & (-xor_all) isolates the rightmost set bit
        diff_bit = xor_all & (-xor_all)

        # Step 3: Partition and find the two unique numbers in one pass
        num1 = 0
        num2 = 0

        for num in nums:
            if num & diff_bit:
                num1 ^= num
            else:
                num2 ^= num

        return [num1, num2]

class Solution:
    def hIndex(self, citations):
        # Sort citations in descending order
        citations.sort(reverse=True)

        # Find the maximum h such that there are at least h papers 
        # with at least h citations each
        for i in range(len(citations)):
            # At position i (0-indexed), we have i+1 papers
            # If citations[i] >= i+1, then we have at least i+1 papers 
            # with at least i+1 citations each
            if citations[i] < i + 1:
                return i

        # If we've gone through all papers, return the length
        return len(citations)

# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def inorderSuccessor(self, root: TreeNode, p: TreeNode) -> TreeNode:
        successor = None
        current = root

        while current:
            if current.val > p.val:
                successor = current
                current = current.left
            else:
                current = current.right

        return successor

class Solution:
    def removeInvalidParentheses(self, s):
        def is_valid(string):
            """Check if parentheses are balanced"""
            count = 0
            for char in string:
                if char == '(':
                    count += 1
                elif char == ')':
                    count -= 1
                    if count < 0:
                        return False
            return count == 0

        def get_remove_count(s):
            """Get count of unmatched opening and closing parentheses"""
            left = right = 0
            for char in s:
                if char == '(':
                    left += 1
                elif char == ')':
                    if left > 0:
                        left -= 1
                    else:
                        right += 1
            return left, right

        # Get the number of parentheses to remove
        left_remove, right_remove = get_remove_count(s)

        result = set()

        def backtrack(index, current, left_count, right_count, left_remove, right_remove):
            # Base case: reached end of string
            if index == len(s):
                if left_remove == 0 and right_remove == 0 and left_count == 0:
                    result.add(current)
                return

            char = s[index]

            if char == '(':
                # Option 1: Include this '('
                if left_remove > 0:
                    backtrack(index + 1, current, left_count, right_count, left_remove - 1, right_remove)
                # Option 2: Don't include this '('
                backtrack(index + 1, current + char, left_count + 1, right_count, left_remove, right_remove)

            elif char == ')':
                # Option 1: Include this ')'
                if right_remove > 0:
                    backtrack(index + 1, current, left_count, right_count, left_remove, right_remove - 1)
                # Option 2: Don't include this ')'
                if left_count > 0:
                    backtrack(index + 1, current + char, left_count - 1, right_count + 1, left_remove, right_remove)
                # If we can't use it (no matching open), we must remove it
                # But we already handled removal above
            else:
                # Regular character, always include
                backtrack(index + 1, current + char, left_count, right_count, left_remove, right_remove)

        # Start backtracking
        backtrack(0, "", 0, 0, left_remove, right_remove)

        # Convert set to list
        return list(result) if result else [""]

from collections import deque, defaultdict

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

    @staticmethod
    def from_list(arr):
        if not arr:
            return None
        root = TreeNode(arr[0])
        queue = [root]
        i = 1
        while queue and i < len(arr):
            node = queue.pop(0)
            if arr[i] is not None:
                node.left = TreeNode(arr[i])
                queue.append(node.left)
            i += 1
            if i < len(arr) and arr[i] is not None:
                node.right = TreeNode(arr[i])
                queue.append(node.right)
            i += 1
        return root

class Solution:
    def verticalOrder(self, root):
        if not root:
            return []

        # Dictionary to store nodes by their column index
        column_map = defaultdict(list)

        # Queue for BFS: (node, column_index)
        queue = deque([(root, 0)])

        # Track min and max column indices using single variables
        min_col = 0
        max_col = 0

        # Process nodes in BFS order
        while queue:
            node, col = queue.popleft()

            # Add node value to its column - direct assignment without min/max
            column_map[col].append(node.val)

            # Update column bounds efficiently
            if col < min_col:
                min_col = col
            elif col > max_col:
                max_col = col

            # Add children to queue with updated column indices
            if node.left:
                queue.append((node.left, col - 1))
            if node.right:
                queue.append((node.right, col + 1))

        # Build result using list comprehension for better performance
        return [column_map[col] for col in range(min_col, max_col + 1)]
